internal object VectorStoresCreateVectorStoreFileOperation {
    /**
     * Creates an attachment between a file and a vector store. Supply the file's `file_id` and
     * optionally configure `chunking_strategy` or attach `attributes`; use file batches for
     * multi-file ingestion. The response includes the attached file's processing status.
     *
     * Create a vector store file by attaching a File to a vector store.
     *
     * @param vectorStoreId The ID of the vector store for which to create a File.
     * @param fileId A File ID that the vector store should use. Useful for tools like `file_search`
     *   that can access files. For multi-file ingestion, we recommend `file_batches` to minimize
     *   per-vector-store write requests.
     * @param chunkingStrategy The chunking strategy used to chunk the file(s). If not set, will use
     *   the `auto` strategy.
     * @param attributes Set of 16 key-value pairs that can be attached to an object. This can be
     *   useful for storing additional information about the object in a structured format, and
     *   querying for objects via API or the dashboard. Keys are strings with a maximum length of 64
     *   characters. Values are strings with a maximum length of 512 characters, booleans, or
     *   numbers.
     */
    fun createVectorStoreFile(
        clientConfig: ClientConfig,
        vectorStoreId: String,
